def reproduce(
    self, copy_paths: Optional[list[str]] = None, message: Optional[str] = None
) -> Mapping[str, Mapping[str, str]]:
    """Reproduce queued experiments using celery workers.

    Args:
        copy_paths: Optional list of paths to copy into the experiment workspace
        message: Optional commit message template

    Returns:
        Mapping of experiment revisions to their results
    """
    results = {}
    for entry in self.iter_queued():
        result = self.get_result(entry)
        if result and result.exp_hash and result.ref_info:
            results[entry.stash_rev] = {str(result.ref_info): result.exp_hash}
    return results

